import{_ as i,o as s,c as t,a4 as o}from"./chunks/framework.BE47AOxC.js";const f=JSON.parse(`{"title":"Accueil","description":"","frontmatter":{"layout":"home","title":"Accueil","hero":{"name":"Teuthis-CMS","text":"Le CMS des collectivités","tagline":"Une API et un back-office pour gérer le contenu d'un site, que l'on installe sur son propre serveur avec une commande, selon son usage.","actions":[{"theme":"brand","text":"Installer Teuthis","link":"/installer/"},{"theme":"alt","text":"Lire la documentation","link":"/documentation/"}]}},"headers":[],"relativePath":"index.md","filePath":"index.md"}`),a={name:"index.md"};function n(r,e,l,u,c,d){return s(),t("div",null,[...e[0]||(e[0]=[o('<h2 id="ce-quest-teuthis" tabindex="-1">Ce qu&#39;est Teuthis-CMS <a class="header-anchor" href="#ce-quest-teuthis" aria-label="Permalink to &quot;Ce qu&#39;est Teuthis-CMS {#ce-quest-teuthis}&quot;">​</a></h2><p>Teuthis-CMS est un logiciel de gestion de contenu (CMS) libre, sous licence Apache 2.0, pensé pour les sites web des collectivités et administrations françaises, mais utilisable par toute organisation. Il se compose d&#39;une <strong>API</strong> (FastAPI) et d&#39;un <strong>back-office</strong> (Nuxt) qui l&#39;administre ; un <strong>front de démarrage</strong> optionnel peut afficher le site public.</p><p>Trois engagements structurent le produit :</p><ul><li><strong>Il fonctionne entièrement sans intelligence artificielle.</strong> L&#39;IA est une option qu&#39;on peut activer plus tard ; aucune fonction essentielle n&#39;en dépend.</li><li><strong>Rien ne se code.</strong> Types de contenu, pages, droits d&#39;accès : tout se fait depuis le back-office, sans écrire de code ni faire de migration de base de données.</li><li><strong>Il est pensé pour le cadre français</strong> : RGPD, accessibilité numérique, gestion des cookies, protection des données personnelles.</li></ul><h2 id="un-profil-par-usage" tabindex="-1">Un profil par usage <a class="header-anchor" href="#un-profil-par-usage" aria-label="Permalink to &quot;Un profil par usage {#un-profil-par-usage}&quot;">​</a></h2><p>On choisit son métier au départ : l&#39;instance naît avec les extensions qui lui conviennent, et chaque extension reste installable ou désinstallable une par une ensuite. Cette liste est lue dans les fichiers de profil du dépôt à chaque construction du site.</p><h3 id="profil-collectivite" tabindex="-1">Collectivité <a class="header-anchor" href="#profil-collectivite" aria-label="Permalink to &quot;Collectivité {#profil-collectivite}&quot;">​</a></h3><p>Le pack secteur public : annuaires, actualités, agenda, démarches en ligne, cartographie. De quoi ouvrir le site d&#39;une commune ou d&#39;un établissement public avec ses démarches courantes.</p><p><strong>Ce que ce profil ne fait pas.</strong></p><ul><li>FranceConnect et l&#39;antivirus des pièces jointes sont proposés mais inactifs tant qu&#39;ils ne sont pas configurés par l&#39;exploitant.</li></ul><details><summary>Extensions installées (23)</summary><p><code>annuaire_lieux</code>, <code>annuaire_personnes</code>, <code>annuaire_elus</code>, <code>annuaires_structure</code>, <code>actualites</code>, <code>agenda</code>, <code>publications</code>, <code>albums</code>, <code>paroles_acteurs</code>, <code>faq</code>, <code>glossaire</code>, <code>flash_info</code>, <code>marches_publics</code>, <code>offres_emploi</code>, <code>rdv_reservations</code>, <code>sondages</code>, <code>enquetes</code>, <code>sve</code>, <code>calendrier_travaux</code>, <code>cartography</code>, <code>navigation</code>, <code>accordeon</code>, <code>widgets_accueil</code></p></details><p><a href="/teuthis-cms-distribution/installer/?profil=collectivite">Installer ce profil</a> — clé <code>collectivite</code></p><h3 id="profil-blog-presse" tabindex="-1">Blog et presse <a class="header-anchor" href="#profil-blog-presse" aria-label="Permalink to &quot;Blog et presse {#profil-blog-presse}&quot;">​</a></h3><p>Actualités, dossiers, directs, tribunes et podcast : un site éditorial organisé en rubriques, avec des pages auteur et un flux RSS.</p><p><strong>Ce que ce profil ne fait pas.</strong></p><ul><li>Pas de commentaires : l&#39;extension Commentaires n&#39;est qu&#39;une démonstration, sans stockage ni modération, et n&#39;est donc installée par aucun profil.</li></ul><details><summary>Extensions installées (7)</summary><p><code>annuaire_personnes</code>, <code>actualites</code>, <code>redaction</code>, <code>publications</code>, <code>albums</code>, <code>navigation</code>, <code>accordeon</code></p></details><p><a href="/teuthis-cms-distribution/installer/?profil=blog_presse">Installer ce profil</a> — clé <code>blog_presse</code></p><h3 id="profil-portfolio" tabindex="-1">Portfolio <a class="header-anchor" href="#profil-portfolio" aria-label="Permalink to &quot;Portfolio {#profil-portfolio}&quot;">​</a></h3><p>Une grille de réalisations, des fiches projet et des témoignages : un site vitrine pour une agence, un atelier ou un indépendant.</p><details><summary>Extensions installées (6)</summary><p><code>albums</code>, <code>paroles_acteurs</code>, <code>annuaire_personnes</code>, <code>agence</code>, <code>navigation</code>, <code>accordeon</code></p></details><p><a href="/teuthis-cms-distribution/installer/?profil=portfolio">Installer ce profil</a> — clé <code>portfolio</code></p><h3 id="profil-catalogue-devis" tabindex="-1">Catalogue et devis <a class="header-anchor" href="#profil-catalogue-devis" aria-label="Permalink to &quot;Catalogue et devis {#profil-catalogue-devis}&quot;">​</a></h3><p>Un catalogue de produits filtrable, des points de vente et une demande de devis : pour présenter une offre sans vendre en ligne.</p><p><strong>Ce que ce profil ne fait pas.</strong></p><ul><li>Ni panier, ni paiement, ni commande : ce profil présente un catalogue et recueille des demandes de devis, il ne fait pas de vente en ligne.</li></ul><details><summary>Extensions installées (6)</summary><p><code>boutique</code>, <code>albums</code>, <code>paroles_acteurs</code>, <code>cartography</code>, <code>navigation</code>, <code>accordeon</code></p></details><p><a href="/teuthis-cms-distribution/installer/?profil=catalogue_devis">Installer ce profil</a> — clé <code>catalogue_devis</code></p><h3 id="profil-sur-mesure" tabindex="-1">Sur mesure (headless) <a class="header-anchor" href="#profil-sur-mesure" aria-label="Permalink to &quot;Sur mesure (headless) {#profil-sur-mesure}&quot;">​</a></h3><p>Le Core seul, sans extension ni page : l&#39;API est exposée pour le front d&#39;un prestataire.</p><p><strong>Ce que ce profil ne fait pas.</strong></p><ul><li>Aucun site public livré : réservé à qui a un développeur pour construire le front.</li></ul><p>Aucune extension : le Core seul.</p><p><a href="/teuthis-cms-distribution/installer/?profil=sur_mesure">Installer ce profil</a> — clé <code>sur_mesure</code></p><h2 id="ce-que-teuthis-ne-fait-pas" tabindex="-1">Ce que Teuthis ne fait pas <a class="header-anchor" href="#ce-que-teuthis-ne-fait-pas" aria-label="Permalink to &quot;Ce que Teuthis ne fait pas {#ce-que-teuthis-ne-fait-pas}&quot;">​</a></h2><ul><li><strong>Il ne livre pas de site public en dehors du front de démarrage</strong>, et le front de démarrage n&#39;existe pas encore pour tous les profils : voir le tableau « Le site public, selon le profil » du <a href="/teuthis-cms-distribution/installer/guide-pas-a-pas">guide pas à pas</a>. Pour un site sur mesure, l&#39;API est faite pour être consommée par le front d&#39;un prestataire.</li><li><strong>Il ne vend pas en ligne</strong> : le profil « Catalogue et devis » n&#39;a ni panier, ni paiement, ni commande.</li><li><strong>Il n&#39;a pas de commentaires modérés</strong> : l&#39;extension Commentaires n&#39;est qu&#39;une démonstration, et aucun profil ne l&#39;installe.</li><li><strong>Il ne se met pas encore à jour tout seul</strong>, et ne copie pas encore ses sauvegardes ailleurs : voir <a href="/teuthis-cms-distribution/documentation/referent/ce-qui-manque-encore">Ce qui manque encore</a>.</li><li><strong>Il n&#39;affirme aucune conformité juridique à l&#39;AI Act</strong> : sa validation juridique n&#39;est pas faite. Les fonctions d&#39;IA sont optionnelles et désactivées tant qu&#39;aucun fournisseur n&#39;est configuré.</li></ul><p>Les limites propres à chaque profil sont rappelées dans la liste ci-dessus, et par l&#39;installateur avant que vous ne choisissiez.</p><h2 id="pour-aller-plus-loin" tabindex="-1">Pour aller plus loin <a class="header-anchor" href="#pour-aller-plus-loin" aria-label="Permalink to &quot;Pour aller plus loin {#pour-aller-plus-loin}&quot;">​</a></h2><ul><li><a href="/teuthis-cms-distribution/installer/">Installer Teuthis</a> : prérequis, choix du profil et commande d&#39;installation.</li><li><a href="/teuthis-cms-distribution/documentation/">Documentation</a> : la notice d&#39;utilisation et le guide du référent (sauvegarde, mise à jour, dépannage).</li><li><a href="/teuthis-cms-distribution/developpeurs/">Développeurs</a> : référence de l&#39;API, décisions d&#39;architecture et contribution.</li><li><a href="/teuthis-cms-distribution/versions/">Versions</a> : versions publiées et vérification des signatures des images.</li><li><a href="/teuthis-cms-distribution/accessibilite">Accessibilité de ce site</a>.</li></ul>',39)])])}const m=i(a,[["render",n]]);export{f as __pageData,m as default};
